const job = $input.first().json.handoff_job;

const esc = s =>
  String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .slice(0, 140);

const lead = esc(job.lead_id);

const rep =
  job.slack_user_id &&
  /^[UW][A-Z0-9]{6,}$/.test(String(job.slack_user_id))
    ? `<@${job.slack_user_id}>`
    : esc(job.rep_name || 'Assigned representative');

// Notification titles
const labels = {
  handoff: 'New lead assigned',
  reassignment: 'Lead reassigned — action required',
  priority: 'Priority lead needs attention',
  customer_reply: 'Customer replied — human follow-up needed',
  escalation: 'SLA missed — manager intervention',
};

const headline = labels[job.kind] || 'Human handoff';

// Lead information
const details = [
  `*Lead:* ${lead}`,
  `*Customer:* ${esc(job.first_name)}`,
  `*Source:* ${esc(job.source)}`,
  `*Priority:* ${esc(job.priority)} (score ${
    job.score == null ? 'pending' : Number(job.score)
  })`,
  `*Engagement:* ${esc(job.engagement || 'none')}`,
  job.qualification_summary
    ? `*Qualification:* ${esc(job.qualification_summary)}`
    : '*Qualification:* Pending',
  `*Owner:* ${rep}`,
  `*Stage:* ${esc(job.lead_state)}`,
  job.due_at
    ? `*Claim deadline:* ${esc(job.due_at)}`
    : '*Claim deadline:* Manager escalation',
].join('\n');

// Slack message blocks
const blocks = [
  {
    type: 'header',
    text: {
      type: 'plain_text',
      text: headline.slice(0, 150),
    },
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: details.slice(0, 2800),
    },
  },
  {
    type: 'context',
    elements: [
      {
        type: 'mrkdwn',
        text:
          'A customer reply does NOT claim a lead. ' +
          'Only the currently authorized representative ' +
          'can claim an assigned lead. ' +
          'Manager escalations require manual intervention.',
      },
    ],
  },
];

// Show Claim Lead only for eligible handoff/priority/reassignment cards.
// Customer replies and manager escalations never show this button.
if (
  job.can_claim &&
  !['customer_reply', 'escalation'].includes(job.kind)
) {
  blocks.push({
    type: 'actions',
    elements: [
      {
        type: 'button',
        action_id: 'engine1_c04_claim',
        text: {
          type: 'plain_text',
          text: 'Claim Lead',
        },
        style: 'primary',
        value: `${job.lead_id}|${job.assignment_version}`,
      },
    ],
  });
}

// Return Slack request and notification metadata
return [
  {
    json: {
      notification_id: job.notification_id,
      claim_token: job.claim_token,
      slack_request: {
        channel: String(job.channel),
        text: `${headline}: ${job.lead_id}`,
        blocks,
        unfurl_links: false,
        unfurl_media: false,
      },
    },
  },
];

const j = $('H3 · Compose Assigned-Rep Slack Card').first().json;
const r = $input.first()?.json ?? {};
let body=r.body ?? {}; if(typeof body==='string'){try{body=JSON.parse(body)}catch{body={}}}
const http = Number(r.statusCode ?? 0) || null;
const ok = http===200 && body?.ok===true && typeof body.ts==='string' && typeof body.channel==='string';
let outcome='unknown';
if(ok) outcome='posted';
else if(http===429) outcome='retryable';
else if(http && http>=400 && http<500) outcome='failed';
else if(http===200 && body?.ok===false) outcome='failed';
// Network errors, timeouts and 5xx are ambiguous: never retry blindly.
const err=String(body?.error ?? r.error?.message ?? (http?`http_${http}`:'transport_unknown')).slice(0,140);
return [{json:{notification_id:j.notification_id,claim_token:j.claim_token,
 result:outcome,http_status:http,channel_id:ok?body.channel:null,
 slack_ts:ok?body.ts:null,error_code:ok?null:err}}];

// Raw form bytes MUST be preserved. Reject if n8n parsed/changed the body.
const req=$input.first(),j=req.json||{};
const h=Object.fromEntries(Object.entries(j.headers||{}).map(([k,v])=>[k.toLowerCase(),String(v)]));
let raw=null;
if(typeof j.body==='string') raw=j.body;
else if(typeof j.rawBody==='string') raw=j.rawBody;
else if(j.body?.type==='Buffer'&&Array.isArray(j.body.data)) raw=Buffer.from(j.body.data).toString('utf8');
else if(req.binary?.data?.data) raw=Buffer.from(req.binary.data.data,'base64').toString('utf8');
const timestamp=String(h['x-slack-request-timestamp']||'');
const signature=String(h['x-slack-signature']||'');
const pre_valid=typeof raw==='string'&&raw.length>0&&raw.length<=20000&&
 /^\d{10,11}$/.test(timestamp)&&/^v0=[0-9a-f]{64}$/.test(signature)&&
 Math.abs(Math.floor(Date.now()/1000)-Number(timestamp))<=300;
return [{json:{pre_valid,raw:pre_valid?raw:'',timestamp,signature,
 base_string:pre_valid?`v0:${timestamp}:${raw}`:''}}];

const j = $input.first().json;

let out = {
  valid: false,
  reason: 'signature_or_payload_invalid'
};

try {
  // 1. Verify Slack HMAC signature
  const actual = 'v0=' + String(j.hmac_hex || '');
  const expected = String(j.signature || '');

  if (actual.length !== 67 || expected.length !== 67) {
    throw Error('invalid_signature_length');
  }

  let diff = 0;

  for (let i = 0; i < 67; i++) {
    diff |= actual.charCodeAt(i) ^ expected.charCodeAt(i);
  }

  if (diff !== 0) {
    throw Error('invalid_signature');
  }

  // 2. Decode Slack form payload without URLSearchParams
  const decodeFormComponent = value =>
    decodeURIComponent(value.replace(/\+/g, ' '));

  let encoded;

  for (const field of j.raw.split('&')) {
    const separator = field.indexOf('=');

    const key = separator === -1
      ? field
      : field.slice(0, separator);

    if (decodeFormComponent(key) !== 'payload') {
      continue;
    }

    if (encoded !== undefined) {
      throw Error('duplicate_payload');
    }

    encoded = decodeFormComponent(
      separator === -1
        ? ''
        : field.slice(separator + 1)
    );
  }

  if (!encoded) {
    throw Error('missing_payload');
  }

  // 3. Parse Slack interaction payload
  const p = JSON.parse(encoded);
  const a = p.actions?.[0];

  if (a?.action_id !== 'engine1_c04_claim') {
    throw Error('wrong_action');
  }

  // 4. Extract lead ID and assignment version
  const [lead, version] = String(a.value || '').split('|');

  if (
    !/^[0-9a-f]{8}-[0-9a-f-]{27,}$/.test(lead) ||
    !/^[1-9]\d{0,7}$/.test(version || '')
  ) {
    throw Error('bad_lead_or_version');
  }

  // 5. Validate Slack actor information
  if (
    !/^[A-Z0-9]{5,25}$/.test(String(p.user?.id || '')) ||
    !p.team?.id ||
    !p.container?.channel_id
  ) {
    throw Error('bad_actor');
  }

  // 6. Generate unique claim action key
  const action_key =
    `${p.team.id}:${p.user.id}:${a.action_ts || j.timestamp}:${lead}`
      .slice(0, 240);

  // 7. Return validated claim
  out = {
    valid: true,
    lead_id: lead,
    assignment_version: Number(version),
    slack_user_id: p.user.id,
    action_key
  };

} catch (e) {
  out = {
    valid: false,
    reason: String(e.message || 'invalid').slice(0, 60)
  };
}

return [{ json: out }];

const incoming=$input.first().json.body;
const allowed=['provider','event_id','lead_id','external_contact_id','kind','owner_id','activity_type',
  'direction','actor_type','occurred_at'];
const valid=incoming && typeof incoming==='object' && !Array.isArray(incoming) &&
 JSON.stringify(incoming).length<=8192 && allowed.slice(0,5).every(k=>typeof incoming[k]==='string');
const evt={}; if(valid) for(const k of allowed) if(typeof incoming[k]==='string') evt[k]=incoming[k].slice(0,300);
return [{json:{valid:Boolean(valid),verified_event:evt}}];

/*
 Engine 1 — Canvas 04
 Build safe Slack message update after atomic claim.

 K1–K7 are unchanged.
 Uses previously verified Slack payload from K2.
 Does not perform database writes or Slack API calls.
*/

const claim = $('K7 · Atomic Claim / Pause Nurture / Sync Owners')
  .first().json.claim_result || {};

const verified = $('K5 · Constant-Time Compare / Extract Claim')
  .first().json;

const raw = $('K2 · Extract Exact Raw Slack Request')
  .first().json.raw;

const skip = reason => [
  { json: { update_ready: false, reason } }
];

try {
  // Only process confirmed claimed states.
  if (!['claimed', 'already_claimed'].includes(claim.action)) {
    return skip('claim_not_confirmed');
  }

  if (verified.valid !== true || typeof raw !== 'string') {
    return skip('unverified_request');
  }

  // Decode the authenticated Slack interaction payload.
  let encoded;

  for (const field of raw.split('&')) {
    const separator = field.indexOf('=');

    const key = decodeURIComponent(
      (separator < 0 ? field : field.slice(0, separator))
        .replace(/\+/g, ' ')
    );

    if (key !== 'payload') continue;

    if (encoded !== undefined) {
      return skip('duplicate_payload');
    }

    encoded = decodeURIComponent(
      (separator < 0 ? '' : field.slice(separator + 1))
        .replace(/\+/g, ' ')
    );
  }

  if (!encoded) return skip('missing_payload');

  const p = JSON.parse(encoded);
  const action = p.actions?.[0];

  // Confirm the card belongs to the verified claim.
  if (
    p.type !== 'block_actions' ||
    action?.action_id !== 'engine1_c04_claim' ||
    action?.value !==
      `${verified.lead_id}|${verified.assignment_version}` ||
    p.user?.id !== verified.slack_user_id
  ) {
    return skip('interaction_mismatch');
  }

  const channel = String(p.container?.channel_id || '');
  const ts = String(p.message?.ts || '');

  if (
    !/^[CGD][A-Z0-9]+$/.test(channel) ||
    !/^\d{10,}\.\d{6}$/.test(ts) ||
    p.channel?.id !== channel ||
    p.container?.message_ts !== ts ||
    !p.message?.bot_id ||
    !Array.isArray(p.message?.blocks)
  ) {
    return skip('invalid_original_message');
  }

  const repId = String(
    claim.rep_id || claim.assigned_rep_id || ''
  );

  if (!repId) return skip('missing_claimed_rep');

  // Preserve original card content.
  const blocks = JSON.parse(
    JSON.stringify(p.message.blocks)
  );

  // Remove the specific Claim Lead button.
  const updatedBlocks = [];
  let removedClaimButton = false;

  for (const block of blocks) {
    if (block.type === 'actions') {
      const elements = (block.elements || []).filter(element => {
        if (
          element.type === 'button' &&
          element.action_id === 'engine1_c04_claim'
        ) {
          removedClaimButton = true;
          return false;
        }

        return true;
      });

      if (elements.length) {
        block.elements = elements;
        updatedBlocks.push(block);
      }

      continue;
    }

    if (block.type === 'header') {
      block.text = {
        type: 'plain_text',
        text: 'Lead claimed',
        emoji: true
      };
    }

    if (block.type === 'section' &&
        block.text?.type === 'mrkdwn') {
      block.text.text = block.text.text
        .replace(
          /^\*Stage:\*.*$/m,
          '*Stage:* CLAIMED'
        )
        .replace(
          /^\*Claim deadline:\*.*(?:\n|$)/m,
          ''
        )
        .trim();
    }

    // Remove the previous instructions to click Claim.
    if (
      block.type === 'context' &&
      (block.elements || []).some(e =>
        String(e.text || '').includes(
          'Claim only as the assigned rep'
        )
      )
    ) {
      continue;
    }

    updatedBlocks.push(block);
  }

  if (!removedClaimButton) {
    return skip('claim_button_not_found');
  }

  updatedBlocks.push({
    type: 'context',
    elements: [{
      type: 'mrkdwn',
      text: `✅ Claimed by representative \`${repId}\`.`
    }]
  });

  return [{
    json: {
      update_ready: true,
      channel,
      ts,
      lead_id: verified.lead_id,
      claim_action: claim.action,
      text: `Lead claimed: ${verified.lead_id}`,
      blocks: updatedBlocks
    }
  }];

} catch (error) {
  return skip('card_build_failed');
}
